import json,sys
from pathlib import Path
R=Path('12_Blender_Model');sys.path.insert(0,str(R/'.local_source_cache/gis_runtime'));import numpy as np
p=R/'reports/R491_LOWER_MOAT_MEASUREMENT.json';d=json.loads(p.read_text())['east_side_lower'];q=np.array(d['controls']);keys=np.floor(q[:,:2]/.6).astype(int);test=(keys[:,0]+3*keys[:,1])%4==0;middle=np.array([-.10513478278620964,.045675689915669115,5.538463984547764]);y0=-34.55;top=middle[0]*q[:,0]+middle[1]*y0+middle[2];t=q[:,1]-y0;slope=float(t[~test]@(q[~test,2]-top[~test])/(t[~test]@t[~test]));coef=[float(middle[0]),slope,float(middle[2]+(middle[1]-slope)*y0)];e=np.c_[q[:,:2],np.ones(len(q))]@coef-q[:,2];d.update(plane=coef,rms=float(np.sqrt(np.mean(e[test]**2))),maxAbsolute=float(abs(e[test]).max()),jointY=y0,exactSharedEdge=True,source='Independent lower-moat planar ramp constrained to existing middle-floor boundary; one new slope fitted on four ground cells, four heldout.');d['valid']=d['rms']<.1 and d['maxAbsolute']<.25;(R/'reports/R491_LOWER_MOAT_CONTINUOUS.json').write_text(json.dumps({'east_side_lower':d},indent=2));print({k:v for k,v in d.items() if k!='controls'})
